it('default selection changed to disabled', () => {
  const sel = container.querySelector('select[data-part=root]');
  expect(sel.value).toBe('disabled');
});
it('regression: button and options unchanged, interactions work', () => {
  const btn = container.querySelector('button[data-part=root]');
  expect(btn.textContent).toBe('提交');
  let clicked = false; btn.addEventListener('click', () => { clicked = true; });
  btn.click(); expect(clicked).toBe(true);
  const sel = container.querySelector('select[data-part=root]');
  expect(Array.from(sel.options).length).toBe(3);
  let changed = null; sel.addEventListener('change', () => { changed = sel.value; });
  sel.value = 'enabled'; sel.dispatchEvent(new Event('change', { bubbles: true }));
  expect(changed).toBe('enabled');
});
